(function(){
  const { jsPDF } = window.jspdf;

  const ENTE_NOME = "CONSORZIO DI BONIFICA DELLA SARDEGNA MERIDIONALE";
  const ENTE_CF = "80000710923";
  const CODICE_CBILL_DEFAULT = "AAU11";

  const OGGETTI = [
    "300 - ONERI PER ATTIVAZIONE UTENZA IDRICA PER USI DIVERSI DA QUELLI IRRIGUI",
    "301 - CONTRIBUTO DI BONIFICA IRRIGUA",
    "305 - SANZIONE AMMINISTRATIVA PER INFRAZIONE IRRIGUA",
    "310 - ONERI ISTRUTTORIA PRATICA IRRIGUA",
  ];
  const COMUNI = [
    ["VILLASOR","CA","09034"], ["GUASILA","CA","09040"], ["NURAMINIS","CA","09024"],
    ["SAMATZAI","CA","09020"], ["SANLURI","SU","09025"], ["SERRAMANNA","SU","09038"],
    ["VILLACIDRO","SU","09039"], ["DECIMOMANNU","CA","09033"], ["MONASTIR","CA","09023"],
    ["SESTU","CA","09028"],
  ];
  const VIE = ["VIA LA GUARDIA","VIA ROMA","VIA GRAMSCI","VIA SARDEGNA","VIA DEI CAMPI",
    "VIA DANTE","VIA IV NOVEMBRE","VIA SAN GIOVANNI","VIA MATTEOTTI","VIA NAZIONALE"];

  function pick(arr){ return arr[Math.floor(Math.random()*arr.length)]; }
  function randDigits(n){ let s=""; for(let i=0;i<n;i++) s+=Math.floor(Math.random()*10); return s; }
  function randInt(min,max){ return Math.floor(Math.random()*(max-min+1))+min; }

  function generaIUV(){
    const iuv = "3000" + randDigits(13) + randDigits(1);
    const gr = [iuv.slice(0,4), iuv.slice(4,8), iuv.slice(8,12), iuv.slice(12,16), iuv.slice(16,18)];
    return { spaziato: gr.join(" "), compatto: iuv };
  }

  function generaCF(){
    const lettere = Array.from({length:6}, () => String.fromCharCode(65+randInt(0,25))).join("");
    const anno = String(randInt(50,99)).padStart(2,"0");
    const mese = pick("ABCDEHLMPRST".split(""));
    const giorno = String(randInt(1,28)).padStart(2,"0");
    const comuneL = String.fromCharCode(65+randInt(0,25));
    const comuneN = randDigits(3);
    const check = String.fromCharCode(65+randInt(0,25));
    return `${lettere}${anno}${mese}${giorno}${comuneL}${comuneN}${check}`;
  }

  function generaIndirizzo(){
    const [comune,prov,cap] = pick(COMUNI);
    const via = pick(VIE);
    const civico = randInt(1,90);
    return { indirizzo: `${via} ${civico}`, capComune: `${cap} ${comune} ${prov}` };
  }

  function parseImporto(v){
    v = String(v).trim().replace("€","").replace(/\s/g,"");
    if (v.includes(",") && v.includes(".")) v = v.replace(/\./g,"").replace(",",".");
    else if (v.includes(",")) v = v.replace(",",".");
    const n = parseFloat(v);
    if (isNaN(n) || n <= 0) throw new Error("Importo non valido");
    return n;
  }

  function fmtImporto(n){
    return n.toLocaleString("it-IT", {minimumFractionDigits:2, maximumFractionDigits:2});
  }

  function fmtDataIt(dateStr){
    const [y,m,d] = dateStr.split("-");
    return `${d}/${m}/${y}`;
  }

  function qrDataUrl(text){
    const qr = qrcode(0, "M");
    qr.addData(text);
    qr.make();
    return qr.createDataURL(4, 2);
  }

  // Hard character-wrap (NOT word-wrap): matches the real avviso, which
  // breaks strictly at the pixel-width limit even mid-word.
  function hardWrap(doc, text, maxWidth){
    const lines = [];
    let cur = "";
    for (const ch of text) {
      const test = cur + ch;
      if (doc.getTextWidth(test) > maxWidth && cur.length > 0) {
        lines.push(cur);
        cur = ch;
      } else {
        cur = test;
      }
    }
    if (cur.length) lines.push(cur);
    return lines;
  }

  function setFont(doc, key, bold){
    if (key === "titillium") doc.setFont("Titillium", bold ? "bold" : "normal");
    else if (key === "roboto") doc.setFont("Roboto", bold ? "bold" : "normal");
    else doc.setFont("RobotoMono", bold ? "bold" : "normal");
  }

  function registerFonts(doc){
    const F = window.__FONTS__;
    doc.addFileToVFS("Titillium-Regular.ttf", F.titilliumRegular);
    doc.addFont("Titillium-Regular.ttf", "Titillium", "normal");
    doc.addFileToVFS("Titillium-Bold.ttf", F.titilliumBold);
    doc.addFont("Titillium-Bold.ttf", "Titillium", "bold");
    doc.addFileToVFS("Roboto-Regular.ttf", F.robotoRegular);
    doc.addFont("Roboto-Regular.ttf", "Roboto", "normal");
    doc.addFileToVFS("Roboto-Bold.ttf", F.robotoBold);
    doc.addFont("Roboto-Bold.ttf", "Roboto", "bold");
    doc.addFileToVFS("RobotoMono-Regular.ttf", F.monoRegular);
    doc.addFont("RobotoMono-Regular.ttf", "RobotoMono", "normal");
    doc.addFileToVFS("RobotoMono-Bold.ttf", F.monoBold);
    doc.addFont("RobotoMono-Bold.ttf", "RobotoMono", "bold");
  }

  function generaPDF(data){
    const doc = new jsPDF({ unit: "pt", format: [595, 841] });
    registerFonts(doc);
    const IMG = window.__IMAGES__;

    // --- gray section-header bands (exact rects from the original) ---
    doc.setFillColor(220,220,220);
    const bands = [
      [15.4, 115.15, 299.25-15.4, 132.4-115.15],
      [300.75, 115.15, 582.4-300.75, 132.4-115.15],
      [15.4, 258.15, 299.25-15.4, 275.4-258.15],
      [300.75, 258.15, 582.4-300.75, 275.4-258.15],
      [15.4, 450.15, 582.4-15.4, 467.4-450.15],
    ];
    bands.forEach(([x,y,w,h]) => doc.rect(x,y,w,h,"F"));

    // --- logos & icons (extracted from the real avviso) ---
    doc.addImage(IMG.logoPagopa, "PNG", 28, 15, 38, 26.7);
    doc.addImage(IMG.logoCbsm, "PNG", 509.25, 13.15, 72, 99.75);
    doc.addImage(IMG.iconPhone, "PNG", 526.15, 299.65, 36.65, 36.75);
    doc.addImage(IMG.iconLocation, "PNG", 526.15, 356.4, 36.65, 36.75);

    // --- all fixed literal text, exact positions/fonts/sizes/colors ---
    window.__FIXED_SPANS__.forEach(([x,y,size,bold,font,color,text]) => {
      const fixedText = String(text || "").trim() === "RATA UNICA" && data.rateLabel
        ? `  ${String(data.rateLabel).toUpperCase()} `
        : text;
      doc.setFontSize(size);
      setFont(doc, font, !!bold);
      doc.setTextColor(color);
      doc.text(fixedText, x, y);
    });

    // --- variable data ---
    doc.setTextColor(0,0,0);

    // CF destinatario (top right)
    doc.setFontSize(9); setFont(doc,"titillium",true); doc.setTextColor("#262626");
    doc.text(data.cf, 465.75, 127.15);

    // Nome / indirizzo / cap destinatario (top right block)
    doc.setFontSize(9.75); setFont(doc,"mono",false); doc.setTextColor(0,0,0);
    doc.text(data.nome, 313.65, 156.65);
    doc.text(data.indirizzo, 313.65, 168.15);
    doc.text(data.capComune, 313.65, 179.40);

    // Scadenza — "RATA UNICA entro il ..." (right-aligned)
    doc.setFontSize(9); setFont(doc,"mono",true); doc.setTextColor("#262626");
    doc.text(data.scadenzaStr, 578, 462.90, { align: "right" });

    // Importo grande + scadenza grande ("QUANTO E QUANDO PAGARE?")
    doc.setFontSize(15.75); setFont(doc,"mono",true); doc.setTextColor(0,0,0);
    doc.text(data.importoStr, 28.55, 317.65);
    doc.text(data.scadenzaStr, 201.50, 317.65);

    // Nome destinatario + importo (riquadro BANCHE E ALTRI CANALI)
    doc.setFontSize(7.5); setFont(doc,"mono",true); doc.setTextColor(0,0,0);
    doc.text(data.nome, 306.00, 496.15);
    doc.setFontSize(11.25);
    doc.text(data.importoStr, 578, 495.65, { align: "right" });

    // Oggetto del pagamento — riquadro basso (hard-wrap, come l'originale)
    doc.setFontSize(7.5); setFont(doc,"mono",true);
    hardWrap(doc, data.oggetto, 227.75).forEach((line,i) => {
      doc.text(line, 347.25, 526.15 + i*9);
    });

    // IUV
    doc.setFontSize(9); setFont(doc,"mono",true);
    doc.text(data.iuvSpaziato, 327.60, 565.90);

    // Codice CBILL (se diverso dal default)
    doc.setFontSize(9); setFont(doc,"mono",true);
    doc.text(data.cbill, 258.00, 565.90);

    // Oggetto — intestazione in alto (hard-wrap identico all'originale)
    doc.setFontSize(12.75); setFont(doc,"mono",true);
    hardWrap(doc, data.oggetto, 372).forEach((line,i) => {
      doc.text(line, 32.20, 73.95 + i*18.8);
    });

    // --- QR code (contenuto reale nel formato ufficiale pagoPA) ---
    const qrPayload = `PAGOPA|002|${data.iuvCompatto}|${ENTE_CF}|${data.importoCents}`;
    try {
      const qrUrl = qrDataUrl(qrPayload);
      doc.addImage(qrUrl, "PNG", 170.8, 487.15, 76.7, 76.7);
    } catch(e){ /* fallback: skip QR if it fails */ }

    // --- watermark di test ---
    doc.setFont("Titillium","normal");
    doc.setFontSize(8);
    doc.setTextColor(200,0,0);
    doc.text("DOCUMENTO DI TEST - NON VALIDO PER IL PAGAMENTO", 297.5, 815, { align: "center" });

    return doc;
  }

  function normalizeTestInput(input){
    input = input || {};
    const nome = String(input.nome || "").trim();
    const importo = parseImporto(input.importo);
    const scadenzaRaw = String(input.scadenza || "").trim();
    const oggetto = String(input.oggetto || "").trim();
    const indirizzo = String(input.indirizzo || "").trim();
    const capComune = String(input.capComune || "").trim();
    const cf = String(input.cf || "").trim().toUpperCase();
    const cbill = String(input.cbill || CODICE_CBILL_DEFAULT).trim().toUpperCase() || CODICE_CBILL_DEFAULT;
    if (!nome) throw new Error("Inserire il destinatario");
    if (!scadenzaRaw || !/^\d{4}-\d{2}-\d{2}$/.test(scadenzaRaw)) throw new Error("Inserire una scadenza valida");
    if (!oggetto) throw new Error("Inserire l'oggetto del pagamento");
    if (!indirizzo) throw new Error("Inserire l'indirizzo del destinatario");
    if (!capComune) throw new Error("Inserire CAP e Comune del destinatario");
    if (!cf) throw new Error("Inserire il codice fiscale/P. IVA del destinatario");

    let iuvSpaziato, iuvCompatto;
    const rawCode = String(input.codiceAvviso || "").replace(/\s/g, "");
    if (rawCode) {
      if (!/^\d{18}$/.test(rawCode)) throw new Error("Il codice avviso deve contenere 18 cifre");
      iuvCompatto = rawCode;
      iuvSpaziato = [rawCode.slice(0,4), rawCode.slice(4,8), rawCode.slice(8,12), rawCode.slice(12,16), rawCode.slice(16,18)].join(" ");
    } else {
      const g = generaIUV();
      iuvSpaziato = g.spaziato;
      iuvCompatto = g.compatto;
    }

    return {
      nome: nome.toUpperCase(), importo, importoStr: fmtImporto(importo),
      importoCents: Math.round(importo * 100),
      scadenzaStr: fmtDataIt(scadenzaRaw), oggetto: oggetto.toUpperCase(),
      indirizzo: indirizzo.toUpperCase(), capComune: capComune.toUpperCase(),
      cf, cbill, iuvSpaziato, iuvCompatto,
      rateLabel: String(input.rateLabel || "RATA UNICA").trim() || "RATA UNICA"
    };
  }

  window.__GII_PAGOPA_TEST_GENERATOR__ = {
    enteNome: ENTE_NOME,
    enteCf: ENTE_CF,
    defaultCbill: CODICE_CBILL_DEFAULT,
    generateCode: generaIUV,
    generatePdfBlob: function(input){
      const data = normalizeTestInput(input);
      const doc = generaPDF(data);
      return {
        blob: doc.output("blob"),
        filename: `bollettino_${data.iuvCompatto}.pdf`,
        codiceAvviso: data.iuvCompatto,
        iuv: data.iuvCompatto.slice(1),
        importo: data.importo,
        scadenza: String(input.scadenza || "")
      };
    }
  };
})();
